from functools import cmp_to_key


def compare(a, b):
    if a + b > b + a:
        return -1  # a goes first
    if a + b < b + a:
        return 1   # b goes first
    return 0


for nums in [[10, 2], [3, 30, 34, 5, 9], [0, 0]]:
    pieces = sorted(map(str, nums), key=cmp_to_key(compare))
    joined = "".join(pieces)
    print(pieces, joined.lstrip("0") or "0")

meetings = [[9, 10], [1, 3], [8, 9], [2, 6], [12, 15], [13, 14]]
meetings.sort()
print("Sorted:", meetings)

merged = []
for start, end in meetings:
    if merged and start <= merged[-1][1]:
        merged[-1][1] = max(merged[-1][1], end)
    else:
        merged.append([start, end])

for start, end in merged:
    print(f"{start}-{end}")
print("Busy blocks:", len(merged))
